# fzf shell integration for bash: key bindings (Ctrl-T, Ctrl-R, Alt-C) and
# ** completion, generated by the pinned binary (see
# .chezmoidata/fzf.yaml) so they always match its version.
#
# Must sort before fzf-tab-completion.bash in ~/.bashrc.d (glob order), which
# then rebinds Tab over fzf's own Tab completion.
if [[ $- == *i* ]] && command -v fzf >/dev/null 2>&1; then
	eval "$(fzf --bash)"
fi
